from pathlib import Path

main_path = Path('app/src/main/java/com/clickgo/passageiro/MainActivity.java')
main = main_path.read_text(encoding='utf-8')

if 'import android.widget.ImageView;' not in main:
    main = main.replace('import android.widget.FrameLayout;\n', 'import android.widget.FrameLayout;\nimport android.widget.ImageView;\n', 1)

old_avatar = '''        TextView avatar = text("CG", 14, YELLOW, true);\n        avatar.setGravity(Gravity.CENTER);\n        avatar.setBackground(round(BLACK, 24, BLACK));\n        top.addView(avatar, new LinearLayout.LayoutParams(dp(48), dp(48)));\n'''
new_avatar = '''        ImageView avatar = new ImageView(this);\n        avatar.setImageDrawable(PassengerAvatar.circleDrawable(this));\n        avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);\n        top.addView(avatar, new LinearLayout.LayoutParams(dp(48), dp(48)));\n'''
if old_avatar not in main:
    raise SystemExit('Bloco de avatar do cabecalho nao encontrado')
main = main.replace(old_avatar, new_avatar, 1)

old_preload = '''        PassengerAvatar.preload(this, token, () -> {\n            if (map != null && origin != null && destination != null) drawRoute();\n        });\n'''
new_preload = '''        PassengerAvatar.preload(this, token, () -> {\n            avatar.setImageDrawable(PassengerAvatar.circleDrawable(this));\n            if (map != null && origin != null && destination != null) drawRoute();\n        });\n'''
if old_preload not in main:
    raise SystemExit('Callback de avatar nao encontrado')
main = main.replace(old_preload, new_preload, 1)

old_route = '''    private void drawRoute() {\n        if (map == null || origin == null || destination == null) return;\n        map.getOverlays().clear();\n        Marker start = new Marker(map);\n        start.setPosition(origin);\n        start.setTitle("Embarque");\n        start.setIcon(PassengerAvatar.markerDrawable(this));\n        start.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        map.getOverlays().add(start);\n        Marker end = new Marker(map);\n        end.setPosition(destination);\n        end.setTitle("Destino");\n        end.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        map.getOverlays().add(end);\n        Polyline line = new Polyline();\n        line.setPoints(Arrays.asList(origin, destination));\n        line.getOutlinePaint().setStrokeWidth(dp(6));\n        line.getOutlinePaint().setColor(Color.rgb(48, 92, 220));\n        map.getOverlays().add(line);\n        map.post(() -> {\n            if (map == null) return;\n            try {\n                BoundingBox box = BoundingBox.fromGeoPoints(Arrays.asList(origin, destination));\n                map.zoomToBoundingBox(box, true, dp(70));\n                map.invalidate();\n            } catch (Exception ignored) {}\n        });\n    }\n'''
new_route = '''    private void drawRoute() {\n        if (map == null || origin == null || destination == null) return;\n        drawRouteOverlays(Arrays.asList(origin, destination));\n        GeoPoint startPoint = new GeoPoint(origin.getLatitude(), origin.getLongitude());\n        GeoPoint endPoint = new GeoPoint(destination.getLatitude(), destination.getLongitude());\n        io.execute(() -> {\n            try {\n                String url = "https://router.project-osrm.org/route/v1/driving/"\n                        + startPoint.getLongitude() + "," + startPoint.getLatitude() + ";"\n                        + endPoint.getLongitude() + "," + endPoint.getLatitude()\n                        + "?overview=full&geometries=geojson&steps=false";\n                JSONObject root = new JSONObject(ApiClient.absoluteGet(url));\n                JSONArray routes = root.optJSONArray("routes");\n                if (routes == null || routes.length() == 0) return;\n                JSONObject geometry = routes.getJSONObject(0).optJSONObject("geometry");\n                JSONArray coords = geometry == null ? null : geometry.optJSONArray("coordinates");\n                if (coords == null || coords.length() < 2) return;\n                List<GeoPoint> roadPoints = new ArrayList<>();\n                for (int i = 0; i < coords.length(); i++) {\n                    JSONArray pair = coords.optJSONArray(i);\n                    if (pair == null || pair.length() < 2) continue;\n                    roadPoints.add(new GeoPoint(pair.optDouble(1), pair.optDouble(0)));\n                }\n                if (roadPoints.size() < 2) return;\n                ui.post(() -> {\n                    if (!destroyed && map != null) drawRouteOverlays(roadPoints);\n                });\n            } catch (Exception ignored) {\n                // Mantem a linha simples como fallback se o roteador estiver indisponivel.\n            }\n        });\n    }\n\n    private void drawRouteOverlays(List<GeoPoint> routePoints) {\n        if (map == null || origin == null || destination == null) return;\n        map.getOverlays().clear();\n        Marker start = new Marker(map);\n        start.setPosition(origin);\n        start.setTitle("Embarque");\n        start.setIcon(PassengerAvatar.markerDrawable(this));\n        start.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        map.getOverlays().add(start);\n\n        Marker end = new Marker(map);\n        end.setPosition(destination);\n        end.setTitle("Destino");\n        end.setAnchor(Marker.ANCHOR_CENTER, Marker.ANCHOR_BOTTOM);\n        map.getOverlays().add(end);\n\n        Polyline line = new Polyline();\n        line.setPoints(routePoints);\n        line.getOutlinePaint().setStrokeWidth(dp(6));\n        line.getOutlinePaint().setColor(Color.rgb(48, 92, 220));\n        map.getOverlays().add(line);\n\n        try {\n            BoundingBox box = BoundingBox.fromGeoPoints(routePoints);\n            map.zoomToBoundingBox(box, true, dp(70));\n        } catch (Exception ignored) {}\n        map.invalidate();\n    }\n'''
if old_route not in main:
    raise SystemExit('Metodo drawRoute esperado nao encontrado')
main = main.replace(old_route, new_route, 1)
main_path.write_text(main, encoding='utf-8')

avatar_path = Path('app/src/main/java/com/clickgo/passageiro/PassengerAvatar.java')
avatar = avatar_path.read_text(encoding='utf-8')
needle = '''    public static String initials() {\n        return initials(fullName);\n    }\n'''
addition = '''    public static Drawable circleDrawable(Context context) {\n        float density = context.getResources().getDisplayMetrics().density;\n        int size = Math.max(48, Math.round(48 * density));\n        Bitmap output = Bitmap.createBitmap(size, size, Bitmap.Config.ARGB_8888);\n        Canvas canvas = new Canvas(output);\n        Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);\n        float cx = size / 2f;\n        float radius = size / 2f - Math.max(1f, density);\n\n        paint.setColor(Color.rgb(255, 212, 0));\n        canvas.drawCircle(cx, cx, radius, paint);\n        float inner = radius - Math.max(3f, 3f * density);\n        Bitmap currentPhoto = photo;\n        if (currentPhoto != null && !currentPhoto.isRecycled()) {\n            int save = canvas.save();\n            Path clip = new Path();\n            clip.addCircle(cx, cx, inner, Path.Direction.CW);\n            canvas.clipPath(clip);\n            Rect src = centerCrop(currentPhoto);\n            RectF dst = new RectF(cx - inner, cx - inner, cx + inner, cx + inner);\n            canvas.drawBitmap(currentPhoto, src, dst, paint);\n            canvas.restoreToCount(save);\n        } else {\n            paint.setColor(Color.rgb(17, 17, 17));\n            canvas.drawCircle(cx, cx, inner, paint);\n            paint.setColor(Color.rgb(255, 212, 0));\n            paint.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));\n            paint.setTextAlign(Paint.Align.CENTER);\n            paint.setTextSize(Math.max(14f, 16f * density));\n            Paint.FontMetrics fm = paint.getFontMetrics();\n            float baseline = cx - (fm.ascent + fm.descent) / 2f;\n            canvas.drawText(initials(fullName), cx, baseline, paint);\n        }\n        return new BitmapDrawable(context.getResources(), output);\n    }\n\n    public static String initials() {\n        return initials(fullName);\n    }\n'''
if needle not in avatar:
    raise SystemExit('Ponto de insercao do avatar circular nao encontrado')
avatar = avatar.replace(needle, addition, 1)
avatar_path.write_text(avatar, encoding='utf-8')

build_path = Path('app/build.gradle')
build = build_path.read_text(encoding='utf-8')
build = build.replace("versionCode 6", "versionCode 7", 1)
build = build.replace("versionName '0.6-native-beta'", "versionName '0.7-native-beta'", 1)
build_path.write_text(build, encoding='utf-8')

print('Passageiro v0.7: rota viaria + avatar no cabecalho aplicados.')
